/* ---------------- dd Mmm yyyy, 24-hour time — the one date/time format used everywhere ----------------
   Deliberately built from getDate()/getMonth()/getHours() etc. rather than toLocaleDateString()/
   toLocaleTimeString() — those follow the browser/OS locale, which on many systems (especially
   US English) renders 12-hour AM/PM regardless of app intent. Manual formatting guarantees
   dd Mmm yyyy + 24-hour HH:mm everywhere, independent of the viewer's locale. */

const PA_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/* Accepts a Date, an ISO date/timestamp string, or null; returns the display dash for
   anything unparseable so callers never print "Invalid Date". */
function paFmtDate(v) {
  if (!v) return '—';
  const d = v instanceof Date ? v : new Date(v);
  if (isNaN(d)) return '—';
  return `${String(d.getDate()).padStart(2, '0')} ${PA_MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}

/* 24-hour HH:mm — the one time format used everywhere a time (not just a date) is shown. */
function paFmtTime(v) {
  if (!v) return '—';
  const d = v instanceof Date ? v : new Date(v);
  if (isNaN(d)) return '—';
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

/* dd Mmm yyyy HH:mm in one call, for the many "Recorded at" / "Generated" style timestamps. */
function paFmtDateTime(v) {
  if (!v) return '—';
  const d = v instanceof Date ? v : new Date(v);
  if (isNaN(d)) return '—';
  return `${paFmtDate(d)} ${paFmtTime(d)}`;
}

/* ---------------- currency (Thai Baht) ---------------- */

/* Full amount with thousands separators: "฿1,250,000" / "—". Used in PDF, CSV, detail page. */
function paFmtBaht(n) {
  return (n == null || !isFinite(n)) ? '—' : '฿' + Math.round(n).toLocaleString('en-US');
}

/* Abbreviated for KPI tiles: "฿2.4M" / "฿450K" / "฿12,000" / "฿0". */
function paFmtBahtShort(n) {
  if (n == null || !isFinite(n)) return '฿0';
  const a = Math.abs(n);
  if (a >= 1e6) return '฿' + (n / 1e6).toFixed(n % 1e6 === 0 ? 0 : 1) + 'M';
  if (a >= 1e3) return '฿' + Math.round(n / 1e3) + 'K';
  return '฿' + Math.round(n).toLocaleString('en-US');
}

/* ---------------- photo downscale ---------------- */

/* Mandatory before any photo is stored or embedded (PDF, Supabase upload) — raw phone
   photos are 3–12 MP. Resolves a JPEG dataURL. */
function downscaleImage(fileOrBlob, maxDim, quality) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(fileOrBlob);
    const img = new Image();
    img.onload = () => {
      try {
        let w = img.naturalWidth, h = img.naturalHeight;
        const scale = Math.min(1, maxDim / Math.max(w, h));
        w = Math.max(1, Math.round(w * scale));
        h = Math.max(1, Math.round(h * scale));
        const canvas = document.createElement('canvas');
        canvas.width = w; canvas.height = h;
        canvas.getContext('2d').drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL('image/jpeg', quality));
      } catch (e) { reject(e); }
      finally { URL.revokeObjectURL(url); }
    };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('image load failed')); };
    img.src = url;
  });
}

