/* ---------------- embedded Google Sans (PDF, base64 TTF) ----------------
   Regular + Bold + Italic + BoldItalic, subsetted to WinAnsi/Latin-1 only (matches this app's
   "WinAnsi-safe characters only" PDF convention -- no CJK/extended glyph coverage kept, which
   is most of Google Sans's stock 1.9MB per weight; subsetting brings each file to ~18KB).
   Source: Google Fonts (fonts.googleapis.com/css2?family=Google+Sans), SIL Open Font License.
   Both pages' PDF builders call registerGoogleSansFonts(doc) once per jsPDF instance before
   using doc.setFont('GoogleSans', ...) -- jsPDF has no other way to use a non-built-in font;
   Courier stays the PDF's numeric/equation font (Google Sans has no monospace variant). The web
   also uses this same embedded font via registerGoogleSansWebFont() below. */
const PA_GOOGLE_SANS_REGULAR = '';
const PA_GOOGLE_SANS_BOLD = '';
const PA_GOOGLE_SANS_ITALIC = '';
const PA_GOOGLE_SANS_BOLDITALIC = '';

function registerGoogleSansFonts(doc) {
  doc.addFileToVFS('GoogleSans-Regular.ttf', PA_GOOGLE_SANS_REGULAR);
  doc.addFont('GoogleSans-Regular.ttf', 'GoogleSans', 'normal');
  doc.addFileToVFS('GoogleSans-Bold.ttf', PA_GOOGLE_SANS_BOLD);
  doc.addFont('GoogleSans-Bold.ttf', 'GoogleSans', 'bold');
  doc.addFileToVFS('GoogleSans-Italic.ttf', PA_GOOGLE_SANS_ITALIC);
  doc.addFont('GoogleSans-Italic.ttf', 'GoogleSans', 'italic');
  doc.addFileToVFS('GoogleSans-BoldItalic.ttf', PA_GOOGLE_SANS_BOLDITALIC);
  doc.addFont('GoogleSans-BoldItalic.ttf', 'GoogleSans', 'bolditalic');
}

/* Make the WEB genuinely use Google Sans (the public Google Fonts API does NOT host it — the old
   <link> silently fell back to Inter). We already carry the font as embedded base64 TTFs for the
   PDF, so reuse those bytes as @font-face data URIs — real Google Sans, offline-safe, ~zero extra
   weight. Only Regular (400) + Bold (700) exist, so weight ranges map 400–500→Regular and
   600–900→Bold (the app's 500/600 labels round to the nearer face). System fallback after it
   covers Thai glyphs, which Google Sans lacks. Runs at parse time (shared.js is non-defer). */
(function registerGoogleSansWebFont() {
  const src = (b64, style, wLo, wHi) =>
    `@font-face{font-family:'Google Sans';font-style:${style};font-weight:${wLo} ${wHi};` +
    `font-display:swap;src:url(data:font/ttf;base64,${b64}) format('truetype');}`;
  const css =
    src(PA_GOOGLE_SANS_REGULAR, 'normal', 400, 500) +
    src(PA_GOOGLE_SANS_BOLD, 'normal', 600, 900) +
    src(PA_GOOGLE_SANS_ITALIC, 'italic', 400, 500) +
    src(PA_GOOGLE_SANS_BOLDITALIC, 'italic', 600, 900);
  const style = document.createElement('style');
  style.id = 'pa-google-sans-face';
  style.textContent = css;
  (document.head || document.documentElement).appendChild(style);
})();
